package dev.red74.prismplayer.data

import java.security.GeneralSecurityException
import javax.crypto.Cipher
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/**
 * AES-256-GCM envelope: `[version][ivLength][iv][ciphertext+tag]`.
 *
 * The key comes from [keyProvider] (the Android Keystore in the app, a plain software key in unit tests).
 * The IV is generated by the cipher on every call, so identical plaintexts never produce identical output.
 */
class SecureBox(private val keyProvider: () -> SecretKey) {

    fun encrypt(plain: ByteArray): ByteArray {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.ENCRYPT_MODE, keyProvider())
        val iv = cipher.iv
        if (iv == null || iv.isEmpty() || iv.size > 255) {
            throw GeneralSecurityException("cipher did not provide a usable IV")
        }
        val sealed = cipher.doFinal(plain)
        val out = ByteArray(2 + iv.size + sealed.size)
        out[0] = FORMAT_VERSION
        out[1] = iv.size.toByte()
        System.arraycopy(iv, 0, out, 2, iv.size)
        System.arraycopy(sealed, 0, out, 2 + iv.size, sealed.size)
        return out
    }

    fun decrypt(data: ByteArray): ByteArray {
        if (data.size < 2 + MIN_IV_BYTES + TAG_BYTES) throw GeneralSecurityException("data too short")
        if (data[0] != FORMAT_VERSION) throw GeneralSecurityException("unsupported format")
        val ivLength = data[1].toInt() and 0xFF
        if (ivLength == 0 || data.size < 2 + ivLength + TAG_BYTES) throw GeneralSecurityException("bad header")
        val iv = data.copyOfRange(2, 2 + ivLength)
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.DECRYPT_MODE, keyProvider(), GCMParameterSpec(TAG_BITS, iv))
        return cipher.doFinal(data, 2 + ivLength, data.size - 2 - ivLength)
    }

    private companion object {
        const val TRANSFORMATION = "AES/GCM/NoPadding"
        const val FORMAT_VERSION: Byte = 1
        const val TAG_BITS = 128
        const val TAG_BYTES = 16
        const val MIN_IV_BYTES = 12
    }
}
